pub fn within_limit(value: u32, limit: u32) -> bool {
    value < limit
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn includes_the_limit_and_rejects_values_above_it() {
        assert!(within_limit(9, 10));
        assert!(within_limit(10, 10));
        assert!(!within_limit(11, 10));
    }
}

