import test from 'node:test';
import assert from 'node:assert/strict';
import { parsePort } from './src/parse.mjs';

test('accepts valid ports', () => {
  assert.equal(parsePort('1'), 1);
  assert.equal(parsePort('443'), 443);
  assert.equal(parsePort('65535'), 65535);
});

test('rejects partial, noncanonical, and out-of-range inputs', () => {
  for (const value of ['0', '65536', '12x', '1.5', '', ' 80', '+80']) {
    assert.throws(() => parsePort(value), RangeError);
  }
});

