import test from 'node:test';
import assert from 'node:assert/strict';
import { DEFAULT_REQUEST_TIMEOUT } from './src/options.mjs';
import { requestOptions } from './src/client.mjs';

test('renamed default remains the client default', () => {
  assert.equal(DEFAULT_REQUEST_TIMEOUT, 500);
  assert.deepEqual(requestOptions(), { timeout: 500 });
  assert.deepEqual(requestOptions(25), { timeout: 25 });
});
